import type { components } from "./schema";

// Names for the API's response shapes; schema.d.ts is generated by `npm run api:types`
type Schemas = components["schemas"];

export type EventSummary = Schemas["EventSummaryResponse"];
export type EventDetail = Schemas["EventDetailResponse"];
export type DivisionCompetitions = Schemas["DivisionCompetitions"];
export type CompetitionSummary = Schemas["CompetitionSummaryResponse"];
export type CompetitionResults = Schemas["CompetitionResultsResponse"];
export type ScoreRow = Schemas["ScoreRow"];
export type Routine = Schemas["Routine"];
export type AllAroundRow = Schemas["AllAroundRow"];
export type TeamRow = Schemas["TeamRow"];
export type ApparatusStandingRow = Schemas["ApparatusStandingRow"];
export type Athlete = Schemas["AthleteRef"];
export type AthleteSummary = Schemas["AthleteSummaryResponse"];
export type AthleteDetail = Schemas["AthleteResponse"];
export type AthleteEntry = Schemas["Entry"];
export type EntryCompetition = Schemas["EntryCompetition"];
export type ApparatusScore = Schemas["ApparatusScore"];

export type Discipline = CompetitionSummary["discipline"];
export type AgeCategory = CompetitionSummary["ageCategory"];
export type CompetitionType = CompetitionSummary["type"];
export type RankingPurpose = NonNullable<CompetitionSummary["purposes"]["team"]>;
export type RankStatus = AllAroundRow["rankStatus"];
export type Apparatus = NonNullable<CompetitionSummary["apparatus"]>;
export type EventLevel = EventSummary["level"];
export type QualificationResult = NonNullable<ScoreRow["qualification"]>;
